const resolveCustomerRequest = `-- name: ResolveCustomerRequest :execrows
UPDATE customer_requests
SET status = $1,
    resolution_note = $2,
    resolved_by = $3,
    resolved_at = $4
WHERE organization_id = $5
  AND id = $6
  AND status = 'open'
`

type ResolveCustomerRequestParams struct {
	Status         string             `json:"status"`
	ResolutionNote string             `json:"resolution_note"`
	ResolvedBy     pgtype.Int8        `json:"resolved_by"`
	ResolvedAt     pgtype.Timestamptz `json:"resolved_at"`
	OrganizationID int64              `json:"organization_id"`
	ID             int64              `json:"id"`
}

func (q *Queries) ResolveCustomerRequest(ctx context.Context, arg ResolveCustomerRequestParams) (int64, error) {
	result, err := q.db.Exec(ctx, resolveCustomerRequest,
		arg.Status,
		arg.ResolutionNote,
		arg.ResolvedBy,
		arg.ResolvedAt,
		arg.OrganizationID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

