const touchPortalSession = `-- name: TouchPortalSession :execrows
UPDATE customer_portal_sessions
SET last_seen_at = $1,
    expires_at = LEAST($2::timestamptz, hard_expires_at)
WHERE organization_id = $3
  AND id = $4
  AND revoked_at IS NULL
`

type TouchPortalSessionParams struct {
	Now            pgtype.Timestamptz `json:"now"`
	ExpiresAt      pgtype.Timestamptz `json:"expires_at"`
	OrganizationID int64              `json:"organization_id"`
	ID             int64              `json:"id"`
}

// Slides the idle expiry (never beyond the hard cap).
func (q *Queries) TouchPortalSession(ctx context.Context, arg TouchPortalSessionParams) (int64, error) {
	result, err := q.db.Exec(ctx, touchPortalSession,
		arg.Now,
		arg.ExpiresAt,
		arg.OrganizationID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
